static struct {
  size_t expected;
  size_t received;
  bool in_progress;
} s_ota_url;

static void ota_url_client_cb(struct mg_connection *c, int ev, void *ev_data) {
  if (ev == MG_EV_CONNECT) {
    MG_INFO(("OTA URL Connected"));
  } else if (ev == MG_EV_HTTP_HDRS) {
    struct mg_http_message *hm = (struct mg_http_message *) ev_data;
    struct mg_str *cl = mg_http_get_header(hm, "Content-Length");
    if (cl != NULL) {
      s_ota_url.expected = atol(cl->buf);
      s_ota_url.received = 0;
      s_ota_url.in_progress = true;
      MG_INFO(("OTA expected size: %lu", s_ota_url.expected));
      glue_ota_begin_firmware_update("url.bin", s_ota_url.expected);
      size_t header_len = hm->body.buf - c->recv.buf;
      mg_iobuf_del(&c->recv, 0, header_len);
    } else {
      MG_ERROR(("OTA URL: No Content-Length"));
      c->is_closing = 1;
    }
  } else if (ev == MG_EV_READ && s_ota_url.in_progress) {
    if (c->recv.len > 0) {
      size_t alignment = 512;
      size_t aligned = (s_ota_url.received + c->recv.len < s_ota_url.expected)
                         ? MG_ROUND_DOWN(c->recv.len, alignment)
                         : c->recv.len;
      if (aligned > 0) {
        glue_ota_write_firmware_update(NULL, c->recv.buf, aligned);
        s_ota_url.received += aligned;
        mg_iobuf_del(&c->recv, 0, aligned);
        if (s_ota_url.received >= s_ota_url.expected) {
          MG_INFO(("OTA URL Complete"));
          glue_ota_end_firmware_update(NULL);
          c->is_closing = 1;
        }
      }
    }
  } else if (ev == MG_EV_CLOSE) {
    if (s_ota_url.in_progress && s_ota_url.received < s_ota_url.expected) {
      MG_ERROR(("OTA URL aborted"));
      glue_ota_abort_firmware_update();
    }
    s_ota_url.in_progress = false;
  }
}

static void glue_start_ota_url(struct mg_connection *c, struct mg_http_message *hm) {
  char url[256] = {0};
  mg_json_get_str2(hm->body, "$.url", url, sizeof(url));
  if (strlen(url) > 0) {
    MG_INFO(("Starting OTA URL: %s", url));
    mg_http_connect(c->mgr, url, ota_url_client_cb, NULL);
    mg_http_reply(c, 200, JSON_HEADERS, "{\"status\":\"ok\"}");
  } else {
    mg_http_reply(c, 400, JSON_HEADERS, "{\"status\":\"error\", \"message\":\"Missing url\"}");
  }
}
struct apihandler_action s_apihandler_ota_url = {{"ota_url", "action", false, 7, 7, 0UL}, NULL, glue_start_ota_url};

static void deferred_factory_reset(void *arg) {
  (void) arg;
  extern void ota_revert_factory(void);
  ota_revert_factory();
}
static void glue_start_factory_reset(struct mg_connection *c, struct mg_http_message *hm) {
  (void) hm;
  mg_http_reply(c, 200, JSON_HEADERS, "{\"status\":\"ok\"}");
  mg_timer_add(&g_mgr, 100, 0, deferred_factory_reset, NULL);
}
